SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for shaanxi_food
-- ----------------------------
DROP TABLE IF EXISTS `shaanxi_food`;
CREATE TABLE `shaanxi_food`  (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `food_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '美食名称',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '美食图片链接',
  `history` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '历史渊源',
  `introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '介绍',
  `features` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '特色',
  `tag` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '美食标签 (如：面食, 小吃, 汤品)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_food_name`(`food_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '陕西美食信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of shaanxi_food
-- ----------------------------
INSERT INTO `shaanxi_food` VALUES (1, '油泼面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/Oil-splashedNoodles.png', '油泼面的历史与关中地区悠久的种麦食面传统及使用动物油脂、植物油脂的饮食习惯密不可分。其“泼油”的技法，可以看作是古代“烹油”技艺在民间面食上的极致应用。这种粗犷而有效的调味方式，源于劳动人民在繁重劳作后对高热量、重口味食物的需求，体现了秦人质朴、豪爽的性格，是陕西面食文化中最具视觉与味觉冲击力的代表之一。', '油泼面是以宽厚的扯面为主料，在煮好的面条上铺上一层厚厚的辣椒面、蒜末、葱花等调料，随后用一勺烧得滚烫的菜油迎头浇下。瞬间，“刺啦”一声，热油激发出调料和面条的复合香气，烟雾蒸腾，香味四溢。食用时拌匀，面条筋道爽滑，味道香辣浓郁，充满了强烈的锅气和生命力。', '滚油泼就：烹制过程的精髓在于那一声“刺啦”响，滚油瞬间锁住香味，是听觉、视觉与味觉的盛宴。\n香辣为主：味道以油泼辣子的焦香和蒜香、葱香为主体，辣而不燥，香气扑鼻。\n面条筋道：底层的面条必须是手工扯制的宽面，口感筋道，能挂住汤汁和油料。\n制作快捷：从煮面到泼油成餐，速度极快，是充满烟火气的“快餐”美食。', '面食');
INSERT INTO `shaanxi_food` VALUES (2, '蘸水面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/DipNoodles.png', '蘸水面源于杨凌当地的农家饭。过去农民在田间劳作，为了省事和共享，便将面条煮好捞在盆中，另调一碗汁子，大家各自夹面蘸食。这种“众人共蘸一盆”的吃法，既方便又增添了饮食的趣味性，后来逐渐演变为今日的“一人一盆一蘸碗”，体现了关中农村朴素的集体生活智慧和因地制宜的饮食创造。', '蘸水面的特点是“白汤绿叶红辣子，面条宽长像裤带”。它分为两大件：一是盛在大碗里、一根一碗、宽长如腰带的光滑筋道面条；另一碗则是精心调制的调味汁（蘸汁）。吃时，将一根面条从面汤中捞起，浸入酸香辛辣的蘸汁中，让面条挂满汤汁再送入口中，集清爽与浓烈于一体。', '面汤分离：独特的“蘸食”法，一蘸一味，体验从清淡到浓烈的味觉转换。\n面条豪迈：单根面条极长极宽，筋道有嚼劲，彰显了西北面食的豪气。\n蘸汁灵魂：蘸汁通常为西红柿、鸡蛋、油泼辣子、香醋等调成的酸汤，开胃爽口。\n定量独特：常以“根”论价，食客按自己的食量点取，饶有趣味。', '面食');
INSERT INTO `shaanxi_food` VALUES (3, '荞面饸饹', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/BuckwheatNoodles.png', '饸饹面的历史非常悠久，其制作工具“饸饹床子”在元代农书中已有明确记载。它的诞生与北方地区广泛种植荞麦、高粱等杂粮的物产背景直接相关。由于荞麦缺乏 gluten，不易擀切，智慧的古人便发明了这种“压”面的工具，使粗糙的杂粮得以制成顺滑的面条。这道美食承载着中国北方杂粮饮食文化的记忆，是古代食品加工机械与饮食智慧结合的典范。', '荞面饸饹是将和好的荞麦面团放入木制或铁制的“饸饹床子”中，通过杠杆原理，用物理压力将面团从底部的多孔模具中直接压入沸水锅中，煮熟后捞出。成品面条呈灰褐色，圆滑长爽，带有荞麦特有的清香。可做汤面，亦可凉拌，口感筋道滑溜，是典型的健康粗粮食品。', '工具压制：使用独特的“饸饹床子”制作，过程充满仪式感，面条形态均匀圆润。\n杂粮健康：主料为荞麦，富含膳食纤维和多种营养素，是公认的健康绿色食品。\n口感独特：面条因压制而格外筋道、滑溜，与手擀面口感迥异。\n吃法多样：著名的有羊肉臊子饸饹、凉拌饸饹等，风味各异，荤素皆宜。', '面食');
INSERT INTO `shaanxi_food` VALUES (4, '子长煎饼', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/Zichang%20pancake.png', '子长煎饼的历史深深植根于陕北黄土高原的农耕文明。其起源与当地的自然物产条件密不可分：子长县地处黄土高原腹地，气候干旱，土壤贫瘠，而耐寒耐旱的荞麦成为这里广泛种植的主要杂粮。古时，先民们为了在艰苦的环境中生存，便将这质朴的谷物磨成面糊，于热鏊上烙成薄饼以充饥，这便是子长煎饼最早的雏形。经过代代相传和技艺的不断精进，这种最初的农家饭食逐渐演变成工艺考究、风味独特的地方名吃。它的命名与这片土地的红色历史息息相关，子长县是为纪念陕北红军和苏区创建人谢子长同志而命名，这款美食也因此承载了深厚的红色文化记忆。如今，子长煎饼的制作技艺已被列入陕西省非物质文化遗产名录，从一味乡土食物升华为代表地方文化与智慧的饮食符号。', '子长煎饼是源自陕西省延安市子长县的一种独特的地方风味小吃，以其“薄如纸、白如玉、韧如绸”而闻名。它并非寻常意义上的厚实面饼，而是以荞麦面糊精制而成的极薄饼皮，可卷馅、可蘸汁，口感软韧滑爽，荞香清雅。在当地，它既是百姓餐桌上的日常主食，也是逢年过节、招待宾朋的必备佳肴，被誉为“陕北一绝”。', '饼皮薄如蝉翼，荞麦制成，口感软韧。\n馅料以豆腐干丝为主，亦有凉菜、肘子等。\n蘸汁为蒜泥醋汤加辣椒油，酸辣开胃。\n食时卷而蘸汁，是待客佳品，亦具粗粮健康特色。', '面食,小吃');
INSERT INTO `shaanxi_food` VALUES (5, '咸汤面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/SaltyNoodleSoup.png', '咸汤面在耀州已有百年以上的传承历史，是典型的市井小吃。它源于民间，为了适应劳动人民快速、实惠、味重的饮食需求而诞生。其独特的咸汤工艺，据传是吸收了当地调味之精华，并经过无数店家不断改良，最终固定下来。这道面食承载了几代耀州人的集体记忆，是观察当地民俗风情最直接的窗口，展现了关中面食文化中粗犷而鲜活的一面。', '咸汤面是耀州人清晨伊始的活力来源。其特点在于一碗用十几种调料熬制的咸香“汤底”，而非面条本身。煮好的面条过水晾凉，食客点餐时，用滚烫的汤反复浇淋数次，瞬间加热。成品面条筋道，汤色黄亮，味道咸香突出，椒麻爽口，一碗下肚，暖身开胃，是极具地方辨识度的“快食”面品。', '汤为灵魂：汤底由多种香料、调料熬制，咸香浓郁，是味道的核心。\n吃法独特：“凉面热汤”，面条提前煮好，售时用热汤“泖”热，出餐极快。\n味道霸道：口味以咸、香、麻为主，花椒味突出，开胃提神，适合早餐。\n经济实惠：亲民的价格和扎实的份量，使其成为真正的百姓日常美食。', '面食');
INSERT INTO `shaanxi_food` VALUES (6, '驴蹄子面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/Lv%20TiziNoodles.png', '关于其起源，有一个广为流传的民间传说：古时一家农户来不及给雇工擀面，主妇情急之下，将和好的面团直接用刀切成厚片下锅，工人吃后却大赞筋道好吃，问其名，主妇看形状便随口答“驴蹄子面”。这个传说反映了它源于民间智慧的应急创造。因其制作快捷、省时省力，且口感独特，便在关中地区流传开来，成为一道深受喜爱的家常面食，体现了陕西人质朴、实在的饮食性格。', '驴蹄子面是一种做法粗犷、口感筋道的“懒人面”。其面条不用复杂的揉擀和饧面，直接用刀将面团切成厚片，形如驴子的蹄子，故得此名。煮熟的面条口感硬实筋韧，有嚼头，通常搭配油泼辣子、臊子、西红柿鸡蛋等浓重调味，吃起来非常过瘾，是关中农家风味的典型代表。', '形状粗犷：面条厚实，断面呈不规则片状，形似驴蹄。\n口感筋道：由于和面硬、省略了饧面过程，口感异常筋韧爽滑，耐咀嚼。\n制作快捷：相比手擀面，制作方法简单快捷，符合“懒人”做法。\n调味豪放：常以酸辣的臊子或浓香的油泼辣子相佐，味道浓郁，非常解馋。', '面食');
INSERT INTO `shaanxi_food` VALUES (7, '羊杂粉丝', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/LambOffalWithGlassNoodles.png', '羊杂粉丝的起源与北方游牧民族和农耕民族的饮食文化融合密切相关。历史上，人们宰羊后，为物尽其用，不舍丢弃内脏，于是将其清洗干净，精心烹制，创造了这道美味。它体现了劳动人民珍惜食材的朴素智慧。在西北、华北等畜牧业发达的地区，这道小吃逐渐成为大众日常饮食的重要组成部分，并发展出各地不同的风味特色，是北方粗犷、豪放饮食文化的典型代表。', '羊杂粉丝是一道以羊杂（包括羊肚、羊肝、羊肺、羊心、羊肠等）和粉丝为主料，配以浓郁羊骨汤烩制而成的风味小吃。其特点是汤色奶白醇厚，羊杂口感多样，或脆嫩或软糯，粉丝吸饱汤汁后爽滑入味。味道鲜香浓郁，回味悠长，是驱寒暖身的绝佳美食，在街头小吃与餐馆中都十分常见。', '内容丰富：集多种羊杂于一碗，口感层次极为丰富，或脆、或嫩、或韧、或糯。\n汤底鲜美：汤头多用羊骨长时间熬制，色白如奶，味道鲜香醇厚，是风味的灵魂。\n粉丝入味：晶莹的粉丝充分吸收汤汁的鲜美和羊杂的荤香，爽滑可口。\n调味自由：食客常可根据个人喜好，加入香菜、辣椒油、陈醋等调料，形成个性化风味。', '汤品,小吃');
INSERT INTO `shaanxi_food` VALUES (8, '岐山臊子面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/QishanSaoZiNoodles.png', '岐山臊子面拥有超过三千年的悠久历史，其起源可追溯至周代。相传源于周文时期，当时人们用牛羊肉熬汤、煮面来祭祀祖先，祭祀完毕后分食，以求祈福禳灾，这便是“嬎汤面”的雏形，后逐渐演变为“臊子面”。它深深植根于周礼文化发祥地的土壤中，其“只吃面、不喝汤”的独特习俗（将汤回锅），以及丰富的文化内涵，使其成为研究中国饮食文化与礼仪制度关联的活态标本，已被列入国家级非物质文化遗产名录。', '岐山臊子面是一款以“酸、辣、香”著称的经典汤面。它集精湛的手工擀面技艺与独特的臊子汤料于一身，讲究“面白薄筋光，油汪酸辣香”。面条需手工擀制，要求筋道爽滑；汤底则酸辣鲜香，色泽油红，配料丰富。它不仅是一道日常美食，更是当地逢年过节、婚丧嫁娶等礼仪场合中不可或缺的象征性食物。', '面条筋道：手工擀制，追求“薄、筋、光”的口感。\n臊子汤灵魂：汤底以陈年香醋和优质辣椒煸炒的“辣子”为核心，形成“酸、辣、香”的主味。\n配色讲究：汤料需有“红（辣油）、黄（蛋皮）、黑（木耳）、绿（蒜苗）、白（豆腐）”五色，美观且营养均衡。\n食俗独特：常有“只吃面、不喝汤”或将汤回锅的习俗，体现了传统的共享与节约精神。', '面食');
INSERT INTO `shaanxi_food` VALUES (9, '擀面皮', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/RollingNoodleDough.png', '擀面皮起源于岐山一带，其历史与当地的农耕文化和面食传统紧密相连。它是由唐代的“冷淘面”演变而来。其独特的洗面和发酵工艺，相传是古代人们在制作面食过程中，为了应对天气、储存等条件而摸索出的智慧结晶。发酵过程产生的微酸风味，成为了擀面皮的标志性味道。从家庭制作到走向市井，擀面皮如今已成为风靡全省乃至全国的特色小吃，展现了陕西民间面食制作的无限创造力。', '擀面皮是陕西凉皮的一种，但制作工艺和口感独树一帜。它是通过洗面、发酵、擀制、蒸熟等多道工序制成。成品面皮色泽微黄，质地非常筋道、柔韧，口感扎实。吃时切成条状，配以面筋，浇上盐水、醋和特制的油泼辣子，拌匀后酸辣开胃，嚼劲十足，是夏季消暑、四季解馋的绝佳风味小吃。', '口感极筋道：因其独特的制作工艺，口感在各类面皮中最为筋道、有嚼头。\n工艺复杂：需经过“洗、沉、发、擀、蒸”等多道工序，技艺要求高。\n风味酸辣：带有天然的发酵微酸，与醋和香浓的油泼辣子结合，形成酸辣爽口的独特风味。\n搭配经典：标配是面皮+面筋+辣油，面筋多孔，能充分吸收料汁，味道浓郁。', '面食,小吃');
INSERT INTO `shaanxi_food` VALUES (10, '扯面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/PulledNoodles.png', '扯面的历史源远流长，其技艺可追溯至千年以前。它源于民间，是陕西家庭主妇和面点师傅的必备技能。在物质相对匮乏的年代，通过精湛的“扯”技，能将有限的面团变成足够多人食用的面条，体现了劳动人民的生活智慧。这种技艺在关中地区尤为普及和发达，成为陕西面食文化根深叶茂的直观体现，承载着深厚的农耕文明和面食传统。', '扯面，顾名思义，是一种通过反复抻、扯、摔、拽等手法，将面团拉制成宽窄、粗细不同面条的手工技艺。它既指这种基础性的制作工艺，也指代由此制成的面条本身。扯出的面条口感筋道、爽滑，富有嚼劲和生命力，是陕西面食体系中最核心、最见功力的技艺之一，为 Biangbiang 面、油泼面等提供了面条载体。', '技法为核心：制作过程充满观赏性，通过揉、醒、搓、扯，将面团化为根根筋道的面条。\n形态多变：可根据喜好和需求，扯出宽如腰带、细如韭叶、或三棱等不同形态的面条。\n口感筋道：由于在反复抻扯中面筋得到充分延展，口感格外爽滑、柔韧、有嚼头。\n应用广泛：是油泼面、臊子面等多种陕西面食的底层制作方式，极具包容性。', '面食');
INSERT INTO `shaanxi_food` VALUES (11, 'Biangbiang 面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/biangbiangNoodle.png', 'Biangbiang 面起源于古都咸阳，是关中“裤带面”的杰出代表。其独特的“Biang”字，被誉为“中国最难写的汉字”，在字典中无法查到，相传是旧时贫穷的赶车人为了解馋创制此面后，为它创造的字，字型蕴含了“辶”（车夫）和“月、田、丝、长”等元素，描绘了关中麦田、饮食、劳作与文化，充满了浓郁的市井智慧和传奇色彩，是底层文化在饮食上的生动反映。关于 biang 一字还有民间流传的歌谣：一点飞上天，黄河两边弯，八字大张口，言字往里走；左一弯，右一弯；左一长，右一长；中间夹个马大王。月字旁，心字底，留个钩搭挂麻糖，推个车车进咸阳', 'Biangbiang 面是扯面的一种极致表现形式，其面条宽度可达三寸以上，长度在一米开外，因其扯制时摔打在案板上发出“BiangBiang”的清脆响声而得名。单碗通常只有三根面条，却足以装满一大碗，形态豪迈奔放，口感兼具筋韧与柔滑，是陕西面食中视觉冲击力最强、文化符号最独特的代表之一。', '字形独特：名称使用结构极其复杂的合字“Biang”，本身就是一个文化奇观和记忆点。\n形态豪放：面条宽如裤带，长如腰带，一根就是一大口，视觉效果震撼。\n口感丰富：边缘柔滑，中心筋道，口感层次分明。\n标配油泼：最经典的吃法是“油泼”，滚烫的菜油浇在辣椒面和蒜末上，“刺啦”一声，香气扑鼻。', '面食');
INSERT INTO `shaanxi_food` VALUES (12, '水盆羊肉', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/LambSoupWithFlatbread.png', '水盆羊肉的历史可追溯至商周时期，其雏形为“羊臐”，是一种用于祭祀的珍贵肉食。至唐宋时期，“山煮羊”的技法已十分流行，这与现今水盆羊肉的清煮技法一脉相承。它得名于因最初常用巨大的粗瓷大碗（形似水盆）盛装。这道美食起源于关中东部，与当地悠久的畜牧业传统及回汉交融的饮食文化密切相关，历经千年演变，已成为关中饮食文化中不可或缺的组成部分。', '水盆羊肉是以大块羊腩肉经长时间炖煮而成的一道汤品。其核心在于一碗清澈金黄、鲜美无比的羊肉清汤，以及炖得极其酥烂、入口即化的羊肉。通常搭配月牙饼或烧饼同食，可将饼掰块泡入汤中，亦可夹入羊肉与小菜。食用时汤鲜肉烂，回味悠长，是驱寒暖身的滋补佳品，尤在冬季备受青睐。', '汤清肉烂：汤色清澈黄亮，味道鲜美醇厚；羊肉炖至极为酥软，不膻不腻。\n吃法多样：标配月牙饼，可泡、可夹，自由搭配，形式丰富。\n滋补暖身：富含营养，是秋冬时节极佳的温补膳食。\n原汤原食：注重突出羊肉和羊汤本身的原汁原味，调味相对简单。', '汤品,主食');
INSERT INTO `shaanxi_food` VALUES (13, '肉夹馍', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/RouJiaMo.png', '肉夹馍的古称是“寒肉馍”，其历史可追溯至战国时期的“寒肉”。而“白吉馍”的技艺则源于咸阳白吉镇，故得名。这道小吃是关中地区千年面食文化与肉食烹制技艺的完美融合，体现了陕西人追求本味、质朴实在的饮食哲学，现已从街头小吃发展为陕西美食的文化符号，走向全世界。', '肉夹馍是将用数十种香料长时间炖煮至酥烂的腊汁肉，切碎后夹入现烤的“白吉馍”中制成的美食。其精髓在于“铁圈虎背菊花心”的白吉馍，皮薄酥脆、馍瓤松软，与肥瘦相间、入口即化的腊汁肉完美结合。肉质丰腴，馍香扑鼻，食用时无需任何辅料，尽显原汁原味的醇厚魅力。', '馍酥肉烂：白吉馍讲究“焦黄酥脆两张皮”，腊汁肉则需炖得酥软香醇，入口即化。\n肥瘦兼宜：可根据喜好选择“纯瘦”、“肥瘦”或“优质”（肉量更多），满足不同口味。\n原汁原味：正宗的肉夹馍不加青椒、香菜等辅料，纯粹以肉和馍的本味取胜。\n便捷美味：手持即食，既是便捷的街头快餐，也是能登大雅之堂的特色美食。', '小吃,主食');
INSERT INTO `shaanxi_food` VALUES (14, '牛羊肉泡馍', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/BeefAndLambStewedBread.png', '泡馍的历史源远流长，其雏形可追溯至西周时期的“牛羊羹”和唐代的“羊羹”。它由古代的宫廷美食“羊羹”演化而来，随着丝绸之路的繁荣，深受西域饮食文化影响，最终在宋元时期形成了与今日相近的吃法。掰馍的过程不仅是饮食的准备，更是一种社交和耐心的体现，承载着西安作为千年古都深厚的历史积淀与饮食智慧。', '牛羊肉泡馍是以优质的牛羊肉与特制的全死面“饦饦馍”为主料。食客需亲手将馍掰成黄豆大小的碎粒，再由厨师用浓郁的牛羊肉汤“冒”（反复浇滚）熟，配以粉丝、肉片，佐以糖蒜、辣酱、香菜食用。成品汤浓馍筋，料重味醇，肉烂汤香，回味无穷。', '吃法讲究：从亲手掰馍到厨师烹制，有一套完整的仪式和术语（如“口汤”、“干泡”、“水围城”）。\n汤浓馍筋：肉汤需熬制十数小时，醇厚鲜美；馍粒煮后筋道入味，久泡不散。\n佐料提味：糖蒜的解腻、辣酱的增香、香菜的清爽，共同构成了丰富的味觉层次。\n营养丰富：兼具主食与菜肴，营养全面，是暖身饱腹的硬核美食。', '汤品,主食');
INSERT INTO `shaanxi_food` VALUES (15, '凉皮', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/ColdSkin.png', '凉皮相传起源于秦始皇时期，距今已有两千多年历史。关于其起源有多个传说，一说是为修建秦始皇陵的工人所创，因天气炎热，米饭变馊，于是创制了不易变质的米皮。另一说则与汉代的开国功臣萧何有关。它源于民间，因其制作原料简单、价格亲民、风味独特而深受百姓喜爱，并因地域和原料差异，发展出了秦镇米皮、汉中热面皮、岐山擀面皮等多个流派。', '凉皮是用面粉（或米粉）洗出的面浆（或米浆）蒸制而成的薄皮，切条后辅以面筋，调上盐水、醋汁和灵魂般的油泼辣子拌匀食用。成品色泽鲜亮，红油诱人，口感或柔嫩或筋道，味道酸辣爽口，清凉解暑，是陕西人夏季餐桌上的绝对主角，也是一年四季都难以割舍的风味。', '流派众多：主要分为米皮（柔嫩）和面皮（筋道），其中面皮又分擀面皮、蒸面皮等，口感各异。\n辣子灵魂：“凉皮好吃全在辣子”，香而不燥、红亮诱人的油泼辣子是决定风味的关键。\n口感爽利：或软糯或筋道，口感清凉爽滑，非常适合夏季食用，开胃解暑。\n搭配经典：“凉皮+肉夹馍+冰峰”饮料，是风靡陕西的“三秦套餐”标配，组合完美。', '小吃');
INSERT INTO `shaanxi_food` VALUES (16, '商州水煎包', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/ShangzhouPan-FriedBuns.png', '水煎包的技艺在全国多地可见，但商州水煎包深深融入了本地饮食风味。其历史可追溯至明清时期，随着南北商贸往来，这种烹饪技法传入商洛山区，并与当地人的口味喜好相结合。商州人选用本地食材制馅，并调整火候与面水比例，形成了独具一格的地方特色，成为商洛饮食文化中市井气息最为浓厚的代表之一。', '商州水煎包是一种集水煮、油煎、蒸汽焖三种烹饪方式于一体的带馅面点。它以发酵面团包裹荤素馅料，在平底锅中码放整齐，经淋水、注油等多道工序煎制而成。成品上软下脆，底面形成一层金黄油亮的焦脆薄壳，口感层次极其丰富，是当地早餐和点心中的明星食品。', '一包三技：融煮、煎、蒸三种烹饪技艺于一体，制作过程颇具观赏性。\n冰花脆底：成品底部连接着一层金黄酥脆的网状薄壳，形似冰花，是其最大特色。\n上软下酥：上部面皮松软，饱含馅料汤汁，下部焦香酥脆，形成双重口感。\n馅料多样：常见韭菜粉条、大肉、牛肉等馅料，丰俭由人，风味各异。', '面食,小吃');
INSERT INTO `shaanxi_food` VALUES (17, '洛南酸汤面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/LuonanSourSoup%20Noodles.png', '洛南酸汤面的起源与当地的气候和物产密切相关。洛南地处秦岭山区，气候湿润，人们需要酸辣的食物来驱赶湿气、开胃健脾。同时，当地盛产优质的粮食醋，为制作酸汤提供了上佳原料。这道面食从农家灶台发展而来，体现了山区人民利用自然物产创造美味、适应环境的朴素智慧，充满了浓厚的乡土气息和家常味道。', '洛南酸汤面是一款汤宽面少的汤面，其灵魂在于一碗酸香适口的“酸汤”。汤底通常用陈醋或浆水点出酸味，辅以辣椒、葱花等提香，味道酸辣平衡，香气扑鼻。面条多为手擀面，筋道爽滑，浸在酸辣的汤中，吃起来暖身开胃，酸香过瘾，是当地人家中常见的暖心美食。', '酸汤为王：汤底酸香爽口，辣味适度，味道鲜明而不过于刺激，开胃生津。\n面筋汤暖：手擀面条筋道，与温热的酸汤一同下肚，暖身暖心，尤其适合寒冷天气。\n制作快捷：属于家常快手饭，从和面到成餐耗时较短，方便日常制作。\n搭配随意：可加入臊子、鸡蛋、青菜等，随意性强，能灵活满足不同口味需求。', '面食');
INSERT INTO `shaanxi_food` VALUES (18, '汉中热米皮', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/HanzhongHotRiceNoodles.png', '汉中热米皮的历史悠久，其起源与汉中盆地湿润的气候和盛产稻米的物产条件直接相关。相传始于秦汉时期，当时的人们将当地出产的稻米磨浆蒸熟，创制了这种易于制作、美味饱腹的小吃。由于汉中地处秦巴山区，气候潮湿，热食更能驱散湿寒，因此“热吃”的习俗被保留并发扬光大，成为汉中饮食文化中不可或缺的核心元素，深深融入当地人的日常生活。', '汉中热米皮是用浸泡好的大米磨成米浆，在热笼屉上快速蒸制成一张洁白光润的米皮，随即取出趁热切条、调味食用。它与关中地区凉吃的面皮形成鲜明对比，口感软糯香滑，米香浓郁。热米皮讲究“热”字，从出笼到入口，过程迅捷，以保持其最佳的温润口感，是唤醒汉中清晨的标志性味道。', '现蒸热吃：最大特色在于“热”字，米皮出笼后立刻调味食用，口感软糯温润。\n米香浓郁：原料为大米，蒸制后散发出纯粹的米脂香气，与小麦面皮风味迥异。\n辣油鲜亮：调味料汁中的辣椒油至关重要，要求色泽红亮、香而不燥，与豆芽等爽口配菜相得益彰。\n早餐标配：是汉中当地人几乎每日必吃的经典早餐，常与菜豆腐搭配成套。', '小吃');
INSERT INTO `shaanxi_food` VALUES (19, '菜豆腐面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/TofuAndVegetableNoodles.png', '菜豆腐面的起源与陕西民间俭朴的饮食智慧有关。在过去，普通百姓为了在饭食中增加内容和营养，便将自家种的青菜和廉价的豆腐一同烹煮，作为面条的浇头或汤底。这种做法既经济实惠，又使得一餐的营养更加均衡。它在汉中等地的流行，也与当地物产和追求清淡原味的饮食偏好相契合，成为了与热米皮相伴相生的经典搭配，体现了民间饮食中荤素搭配、味道调和的朴素哲学。', '菜豆腐面并非指面条由豆腐制成，而是在煮好的手擀面条中，加入了用青菜（如小白菜、油菜）和点制好的嫩豆腐一同烩煮的“菜豆腐”汤卤。成品面条筋道，汤卤清淡，豆腐鲜嫩，青菜爽口，整体风味素雅。它常与口味浓烈的汉中热米皮搭配食用，一浓一淡，形成完美的味觉平衡。', '菜豆腐汤卤：核心是青菜与嫩豆腐同煮的清淡汤卤，味道清鲜，突出食材本味。\n口感丰富：面条筋道，豆腐滑嫩，青菜爽脆，在一碗中呈现多种口感。\n味道清淡：整体调味清淡，盐味较轻，与重口味的食物（如热米皮）是绝佳搭档。\n家常养生：制作简单，食材健康，是一道充满家常味道的养生面食。', '面食');
INSERT INTO `shaanxi_food` VALUES (20, '安康蒸面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/AnkangSteamedNoodles.png', '安康蒸面的历史可追溯至明清时期，其诞生与安康“五方杂处”的移民文化密切相关。作为连接鄂、渝、陕的枢纽，南北饮食文化在此交融。当地人可能借鉴了北方洗面技艺和南方蒸制之法，并结合本地口味，创制了这款小吃。其独特的复合调味，尤其是醋汤的运用，体现了南北风味的融合与创新。历经百年，它已深深融入安康人的血脉，成为这座城市最生动、最浓郁的味觉名片。', '安康蒸面是以面粉洗出的面浆，经过蒸汽蒸制而成的宽厚面皮。其形态与关中的凉皮类似，但口感更为厚实、软糯且富有弹性。出笼后刷上熟油，切成长条，配以豆芽，浇上十多种香料熬制的醋汤和浓郁的芝麻酱，最后淋上一勺灵魂般的油泼辣子。成品口感复合，醋香、酱香、辣香层层递进，是安康人一日之初最惦念的滋味。', '口感厚实软糯：面皮比普通凉皮更厚，口感主打软糯筋韧，饱腹感强。\n复合调味汁：味道核心在于秘制醋汤与芝麻酱的融合，酸香开胃，酱香浓郁，风味独特。\n辣油香而不燥：油泼辣子色泽红亮，注重香气的提炼，辣味柔和而不刺激。\n饮食习俗：是安康人雷打不动的经典早餐，也是深夜慰藉心灵的完美夜宵，承载着浓厚的市井生活气息。', '面食,小吃');
INSERT INTO `shaanxi_food` VALUES (21, '紫阳蒸盆子', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/ZiyangSteamedPotDish.png', '紫阳蒸盆子起源于西汉时期，拥有超过两千年的历史，相传与汉高祖刘邦及汉江流域的船工生活有关。一说为刘邦军旅途中，当地百姓为犒劳军队而创；另一说则为汉江上的船工们为在长途航行中方便就餐，将各种食材共置一盆蒸制，既能饱腹又能补充营养。这道菜深深植根于紫阳的山水之间，融合了当地的物产与饮食智慧，其独特的蒸制技艺和盆器承载着深厚的汉水文化底蕴，已被列入陕西省非物质文化遗产名录。', '紫阳蒸盆子是一道用料极为丰富、工艺讲究的蒸制汤菜。它以整鸡、猪蹄、莲藕、胡萝卜、蛋饺、木耳等多种食材为主料，放入特制的大陶盆中，不加一滴水，完全依靠蒸汽在巨锅中文火慢蒸数小时而成。成品汤色清亮金黄，原汁原味，肉质酥烂脱骨，汤汁鲜美醇厚，是集合了荤素精华、体现团圆美满的盛宴级菜肴。', '原料丰盛：集鸡、猪、蛋、蔬于一盆，食材多样，营养全面，象征团圆富足。\n工艺独特：全程不加水，仅靠蒸汽“逼”出食材原汤，最大程度保留了食物的本味与精华。\n汤鲜肉烂：汤汁清澈而味道极其鲜美醇厚；鸡肉、猪蹄等主料蒸至骨肉分离，入口即化。\n宴席压轴：是年夜饭、婚宴、节庆等重大场合的压轴硬菜，体现了紫阳人待客的最高礼遇。', '菜品,汤品');
INSERT INTO `shaanxi_food` VALUES (22, '葫芦鸡', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/HuluChicken.png', '葫芦鸡的创制相传始于唐代，与当时的礼部尚书韦陟有关。据传其对饮食极为考究，命家厨以先煮后炸的方式烹制鸡肉，前两位厨师未能令其满意而被杀，第三位厨师吸取教训，创新性地加入了“笼蒸”环节，使鸡肉在油炸前已极为香烂，终于成功。这道菜由此诞生，并历经千年传承，成为陕菜技艺与文化的集大成者。', '葫芦鸡是以一只整鸡，经过清煮、笼蒸、油炸三道核心工序精制而成的。成品外形完整，色泽金红，因形似葫芦而得名。食用时，用筷子一拨即骨肉分离，皮酥肉嫩，香烂味醇，蘸以椒盐佐食，风味绝佳，是宴请宾朋时彰显规格与诚意的代表性大菜。', '三道工序：历经煮、蒸、炸三重工艺，流程复杂，技艺要求高，方能达到香酥脱骨的境界。\n形整色艳：成品鸡形如葫芦，色泽金红，造型美观，寓意吉祥。\n口感极致：表皮香酥脆爽，鸡肉鲜嫩多汁，用筷子一触即散，香烂脱骨。\n宴席压轴：是高级宴席上的压轴大菜，体现了陕菜精湛的烹饪技艺与深厚的历史底蕴。', '菜品');
INSERT INTO `shaanxi_food` VALUES (23, '肉丸胡辣汤', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/MeatballSpicySoup.png', '肉丸胡辣汤的历史可追溯至明清时期，由来自西域的穆斯林商人将“胡羹”一类汤食带入西安。在本地化的过程中，为适应关中人的口味，减少了香辛料的种类，突出了花椒的麻，并加入了大量本地蔬菜和手打肉丸，形成了如今汤汁浓稠、食材丰富、风格独特的胡辣汤，成为回民坊饮食文化的标志性符号。', '西安肉丸胡辣汤是以牛肉或羊肉制成的紧实小肉丸，配以土豆、莲花白、胡萝卜、菜花等多种蔬菜，勾入浓芡熬制而成。汤味突出花椒与胡椒复合的麻香与辛辣，汤汁粘稠，食材丰富。食用前淋上油泼辣子，与掰碎的坨坨馍同泡，是唤醒西安清晨最生猛有力的味道。', '麻香突出：味道以花椒的麻和胡椒的辣为主导，香气浓烈，开胃提神。\n食材丰富：内含牛肉丸和多种根茎蔬菜，营养均衡，饱腹感强。\n汤汁浓稠：勾有重芡，汤汁粘稠，能很好地挂在馍块上。\n标配吃法：必须搭配托托馍，掰入汤中同食，是经典的早餐组合。', '汤品,小吃');
INSERT INTO `shaanxi_food` VALUES (24, '甑糕', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/ZaoGao.png', '甑糕的历史极为悠久，其使用的炊具“甑”源于新石器时代，在《战国策》中便有记载。唐代的“烧尾宴”上有一道名为“水晶龙凤糕”的点心，便被推测为现今甑糕的前身。它是由中国古老的“蒸谷米”技艺演变而来，承载着数千年的农耕文明与饮食记忆，是陕西小吃中名副其实的“活化石”。', '甑糕是用糯米、红枣、芸豆为主料，层层铺放在古老的“甑”这种底部有孔的炊具中，经长时间蒸制而成。成品米枣交融，色泽红润，糯米洁白黏润，红枣绵软香甜。口感软糯粘甜，枣香与米香充分融合，是深受老少喜爱的天然风味甜食，常见于早餐摊点。', '古法炊具：使用古老的“甑”锅蒸制，受热均匀，带有独特的器具风味。\n层层铺就：制作时需将米、枣、豆分层铺放，让味道在蒸汽中层层渗透、交融。\n天然甜味：甜味完全来自红枣本身，无额外添加糖，味道自然醇厚。\n口感软糯：糯米粘软，红枣化泥，芸豆香绵，入口甜而不腻，温润滋养。', '小吃,甜品');
INSERT INTO `shaanxi_food` VALUES (25, '菠菜面', 'https://qiqjregvdczjxckgiqan.supabase.co/storage/v1/object/public/NoodlePicture/BocaiNoodle.png', '菠菜面的历史与菠菜在中国的种植历史紧密相连。菠菜原产于波斯，于唐代传入中国，当时是作为稀有蔬菜供奉宫廷。后来在关中这片面食文化极其深厚的土地上，心灵手巧的农家主妇们为了让孩子和家人在吃面的同时能摄入更多蔬菜营养，便创制了这种“藏菜于面”的巧妙方法。它并非某位名厨所创，而是源于民间朴素的饮食智慧，体现了陕西人民在面食制作上的无限创造力与对健康饮食的追求。', '菠菜面是在和面过程中，将新鲜菠菜榨成的汁液替代部分或全部用水，与面粉混合揉制而成的彩色面条。其核心在于天然的色彩与营养的融合。成品面条呈清新的翠绿色，煮熟后色泽鲜亮，在保留面粉筋道口感的同时，又融入了菠菜的淡淡清香。它既可做成油泼面、臊子面，也可凉拌，是色、香、味、养俱佳的面食代表。', '天然色泽：利用菠菜汁天然色素，面条呈现悦目的翠绿色，激发食欲，尤其受儿童喜爱。\n营养升级：在传统碳水之外，额外补充了蔬菜的维生素、膳食纤维和矿物质，实现了主食的营养强化。\n口感筋道：由于蔬菜汁的加入，面团特性发生变化，制作得当的菠菜面口感往往更加筋道、爽滑。\n应用广泛：可作为任何汤面、拌面、炒面的基底，兼具美观与实用，是家庭餐桌上的点睛之笔。', '面食');

SET FOREIGN_KEY_CHECKS = 1;
